// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 guessHash, uint256 lockValue) internal {
        lockValue = bound(lockValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= lockValue);
        uint balBefore = address(c).balance;
        bool settleRevertedBefore;
        try c.settle() {
            settleRevertedBefore = false;
        } catch {
            settleRevertedBefore = true;
        }
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }
        uint balAfter = address(c).balance;
        bool settleRevertedAfter;
        try c.settle() {
            settleRevertedAfter = false;
        } catch {
            settleRevertedAfter = true;
        }
        assertTrue((lockReverted && balAfter == balBefore && settleRevertedAfter == settleRevertedBefore)
            ||
            // Case B: lock succeeded with exactly 1 ether -> balance increased by 1 and settle became no more permissive than before (it may still revert if called too early, but we at least deposited funds)
            (!lockReverted && lockValue == 1 ether && balAfter == balBefore + 1 ether));
    }

    function testFuzz_run(bytes32 guessHash, uint256 lockValue) public {
        _run(guessHash, lockValue);
    }

    receive() external payable {}
}
